def uid_day(uid):
    """The original service day encoded in a stable UID, or None."""
    tail = str(uid).rsplit("-", 1)[-1]
    if len(tail) != 8 or not tail.isdigit():
        return None
    try:
        return date(int(tail[:4]), int(tail[4:6]), int(tail[6:]))
    except ValueError:
        return None


def in_window(uid, start, end):
    """True when a UID's original day falls in [start, end] (unknown days count)."""
    day = uid_day(uid)
    return True if day is None else start <= day <= end


def delta_rows(db, channel, start, end, asof, received, stamp=None):
    """Only what the subscriber does not already hold; -> (changed, withdrawn)."""
    rows = feed_rows(db, channel, start, end, asof, stamp=stamp)
    changed = []
    for row in rows:
        have = received.get(row["uid"])
        if (have is None
                or not same_instant(have.get("utc"), row["utc"])
                or (have.get("status") or STATUS_CONFIRMED) != row["status"]):
            changed.append(dict(row, was=have.get("utc") if have else None,
                                was_status=have.get("status") if have else None))
    scheduled = {row["uid"] for row in rows}
    # A withdrawal only speaks about this window: what the subscriber holds for
    # other service days is none of a package's business.
    withdrawn = [dict(uid=uid, was=row.get("utc"), status=row.get("status"))
                 for uid, row in sorted(received.items())
                 if uid not in scheduled and in_window(uid, start, end)]
    return changed, withdrawn
